            collected = [
                rows[group]
                for item_region, rows in validated
                if item_region == region
                and rows[group]["rate"] is not None
                and rows[group]["uncertainty"] is not None
            ]
            n = len(collected)
            if n < minimum:
                coverage = None
                change = None
                uncertainty = None
